4		"image/color"
5		"testing"
6	)
7	
8	// DEVDESK-751, AC7 (decision Q1-A): the Fix block of a finding detail is written
9	// in ColorText alone, its labels in DetailLabelStyle (bold, ColorText), and the
10	// word "Warning:" carries the warning. ColorDim, ColorSubTitleFg, ColorTitleFg,
11	// ColorWarn and ColorFooterError fall under 4.5:1 on several of the 13 shipped
12	// themes (measured on 2026-11-23), so none of them is used there. ColorDim is
13	// left as it is: it marks a greyed key, an inactive component that WCAG 1.4.3
14	// exempts.
15	
16	// detailMinContrast is WCAG 1.4.3 for text.
17	const detailMinContrast = 4.5
18	
19	// Every style of the block reads on every shipped theme.
20	func TestTheFixBlockStylesReachTextContrastOnEveryTheme(t *testing.T) {
21		eachShippedTheme(t, func(t *testing.T, name string) {
22			for _, ink := range []struct {
23				what string
24				fg   color.Color
25			}{
26				{"ColorText", ColorText},
27				{"DetailLabelStyle", DetailLabelStyle.GetForeground()},
28			} {
29				ratio, err := ContrastRatio(ink.fg, ColorBackground)
30				if err != nil {
31					t.Errorf("theme %s: %s: %v", name, ink.what, err)
32					continue
33				}
34				if ratio < detailMinContrast {
35					t.Errorf("theme %s: %s %s on the background %s is %.2f:1, want >= %.1f:1",
36						name, ink.what, Hex(ink.fg), Hex(ColorBackground), ratio, detailMinContrast)
37				}
38			}
39		})
40	}
41	
42	// The label is bold, in the text colour, on the theme's background, and it follows
43	// the theme that is applied: a style declared once, at the top of styles.go, keeps
44	// the colours of the default theme after ApplyTheme.
45	func REDACTED(t *testing.T) {
46		eachShippedTheme(t, func(t *testing.T, name string) {
47			if !DetailLabelStyle.GetBold() {
48				t.Errorf("theme %s: DetailLabelStyle is not bold: the label would carry nothing but its colour", name)
49			}
50			if got := DetailLabelStyle.GetForeground(); !sameColor(got, ColorText) {
51				t.Errorf("theme %s: DetailLabelStyle foreground = %s, want ColorText %s", name, Hex(got), Hex(ColorText))
52			}
53			if got := DetailLabelStyle.GetBackground(); !sameColor(got, ColorBackground) {
54				t.Errorf("theme %s: DetailLabelStyle background = %s, want ColorBackground %s", name, Hex(got), Hex(ColorBackground))
55			}
56		})
57	}
