func hexRGB(h string) (uint8, uint8, uint8, bool) {
	if len(h) != 7 || h[0] != '#' {
		return 0, 0, 0, false
	}
	var r, g, b uint8
	fmt.Sscanf(h[1:], "%02x%02x%02x", &r, &g, &b)
	return r, g, b, true
}

func TestZZAudit(t *testing.T) {
	names := strings.Split(os.Getenv("AUDIT_THEMES"), ",")
